TypeScript - opt-in idempotency header and custom retry logic:
import {RedwoodClient} from '@redwood/sdk'
import {v4 as uuidv4} from 'uuid'
const client = new RedwoodClient({ apiKey: process.env.RW_KEY })
const headers = { 'Idempotency-Key': uuidv4() }
try {
  const resp = await client.chat.completions.create({ model: 'redwood-chat-1', messages, function_call: ... , headers, retry: 0 })
} catch (err) {
  // implement custom retry with server confirmation endpoint
}

